import{_ as S,l as p,o,b as d,q as r,d as i,f as s,m as t}from"./chunks/framework.Tf23FRXt.js";const m="/assets/866-1.D8hXS--w.png",O="/assets/866-2.BNNYCica.png",T=JSON.parse('{"title":"灿烂神域阿格莱亚","description":"","frontmatter":{},"headers":[{"level":2,"title":"BOSS 1 比尔格","slug":"boss-1-比尔格","link":"#boss-1-比尔格","children":[]},{"level":2,"title":"BOSS 1.5 拉尔戈神使","slug":"boss-1-5-拉尔戈神使","link":"#boss-1-5-拉尔戈神使","children":[]},{"level":2,"title":"BOSS 2 拉尔戈","slug":"boss-2-拉尔戈","link":"#boss-2-拉尔戈","children":[]},{"level":2,"title":"BOSS 2.5 阿格莱亚双狮","slug":"boss-2-5-阿格莱亚双狮","link":"#boss-2-5-阿格莱亚双狮","children":[]},{"level":2,"title":"BOSS 3 阿泽玛","slug":"boss-3-阿泽玛","link":"#boss-3-阿泽玛","children":[]},{"level":2,"title":"BOSS 4 纳尔札尔","slug":"boss-4-纳尔札尔","link":"#boss-4-纳尔札尔","children":[]},{"level":2,"title":"其他参考攻略","slug":"其他参考攻略","link":"#其他参考攻略","children":[]}],"relativePath":"duty/866.htm.md","filePath":"duty/866.md","lastUpdated":1791101830000}'),u={name:"duty/866.htm.md"};function e(k,l,B,a,b,A){const n=p("Role");return o(),d("div",null,[l[18]||(l[18]=r('<h1 id="灿烂神域阿格莱亚" tabindex="-1">灿烂神域阿格莱亚</h1><p>非常炫酷，而且有一定难度，建议适当提升装备再前往挑战。</p><h2 id="boss-1-比尔格" tabindex="-1">BOSS 1 比尔格</h2><div class="guide cols2"><div class="guide col"><img src="'+m+'" width="350px"><p>第二次锤子安全点示意（绿色圆点均为安全点）</p><img src="'+O+'" width="350px"><p>第三次锤子安全点示意（在绿色圆点处等待，地板移动后前往绿方块区域）</p></div><div class="guide col grow"><p>场地出现蓝色圈：击退。锤子发光 + BOSS 脚下出现雷电提示 + 蓝圈时，将会以蓝圈为中心，发生黄色雷电提示的十字或叉字扇形 AOE，调整击退方向时要注意。</p><p>两侧场地消失的动画并没有伤害，两侧消失后，场地图案变为 3x5 的格子。</p><p>场地变化后，长边两侧会出现锤子动画，锤子会将场地横推一格，第一次为演示动画，在中间一列是安全的。</p><p>第二次会在某一行的格子上出现紫色的锤子，并出现紫色的 AOE 范围预警。紫色锤子所在行会被侧面的锤子敲击移动，预判紫色锤子的移动方向，找安全格子躲避。</p><p>第三次 BOSS 会跳到场地一侧，释放覆盖 3x5 格子范围的 AOE。找到 3 行都被 AOE 预警覆盖的行，并前往远离锤子的一边躲避（锤子敲击移动格子后出现安全区）。</p><p>读条<mark>生成分裂体</mark>后，场地东侧（右侧）出现 5 个 BOSS 分身，其中若干个会发光，发光分身的 AOE 行进速度较快。前往不发光分身的面前，待旁边发光分身的 AOE 走过去后，穿过 AOE 躲避剩余伤害。</p></div></div><h2 id="boss-1-5-拉尔戈神使" tabindex="-1">BOSS 1.5 拉尔戈神使</h2><p>读条<mark>坏灭雷斩</mark>，正面 180 度无范围提示 AOE（仅在最后一秒有展示），看到读条就绕到 BOSS 背后。</p><p>抬手出现雷球，2 个雷球会从中央到场边，然后分别绘制 1/4 圆的扇形区域，被圈起来的区域会产生 AOE。</p><p>之后会有一次组合技，先判定雷球的扇形场地，再判定正面的 180 度 AOE，冷静应对即可。</p><h2 id="boss-2-拉尔戈" tabindex="-1">BOSS 2 拉尔戈</h2>',9)),i("p",null,[l[0]||(l[0]=s("BOSS 读条",-1)),l[1]||(l[1]=i("mark",null,"坏灭雷击",-1)),l[2]||(l[2]=s("点名 3 个",-1)),t(n,{name:"tank"}),l[3]||(l[3]=s("T 的时候，T 注意开启减伤并远离人群，这个大伤害技能为范围伤害。",-1))]),l[19]||(l[19]=r('<p>BOSS 背上有 4 个环，作为这个本的核心机制：</p><ul><li>丢出 2 个环放大，2 个小环在手侧，同时读条<mark>幻天破坏拳</mark>并蓄力：观察蓄力手一侧的小环的颜色，这个颜色对应的大环所在半场有 AOE，去异色半场躲避。</li><li>有大环的同时还有彗星落下的标记：若蓄力侧为红色，则彗星落点正下方安全；若蓄力侧为蓝色，则远离落点且红色大环所在半场安全。</li></ul><p>场地出现紫色范围提示，同时有较细的绿线延伸到场地的手指上：绿线表示击退的方向，找绿线一路投影到立起手指，且尽头没有其他 AOE 提示的手指为安全。</p><h2 id="boss-2-5-阿格莱亚双狮" tabindex="-1">BOSS 2.5 阿格莱亚双狮</h2><p>2 头狮子同时读条时，头顶会出现 1、2 的标记，标记为 1 的狮子先放技能，标记为 2 的后方，据此判断回避的时机。</p><p>如果实在躲不来，可以考虑硬吃 1 个技能，但不要 2 个都吃。</p><h2 id="boss-3-阿泽玛" tabindex="-1">BOSS 3 阿泽玛</h2><p>BOSS 读条<mark>两翼红炎风</mark>后，场地上会出现一些红球，这些球是会爆炸的，注意不要肆意走动。</p><p>读条<mark>蜃景</mark>后，会出现一些 BOSS 的分身，这些分身会把面前的球往分身面向所指方向吹过去（可假想为 3x3 的场地，一次吹 1 格），第一次在分身下方躲避较为安全，第二次需要根据分身位置和箭头方向自己寻找安全点。</p>',9)),i("p",null,[l[4]||(l[4]=s("BOSS 读条",-1)),l[5]||(l[5]=i("mark",null,"神炎",-1)),l[6]||(l[6]=s("点名 3 个",-1)),t(n,{name:"tank"}),l[7]||(l[7]=s("T 的时候，T 注意开启减伤并远离人群，这个大伤害技能为范围伤害。",-1))]),l[20]||(l[20]=i("p",null,[s("之后 BOSS 会丢出 2 把扇子，扇子沿着场地周围飞行，当 BOSS 读条"),i("mark",null,"炎扇流舞・终炎"),s("时，扇子会爆炸，范围非常大（与场地半径相同），建议在 BOSS 身下观察扇子位置，待扇子停止飞行后，立刻向没有扇子的方向躲避。")],-1)),l[21]||(l[21]=i("p",null,[s("读条"),i("mark",null,"烈火旋扫"),s("为正面 270° 范围 AOE，仅有背后安全。")],-1)),l[22]||(l[22]=i("p",null,"红炎斩 + 蜃景：场地出现十字地火提示，以及 2 个分身；第一次前往分身所在 1/4 场地躲避，第二次从无分身的场地观察相邻场地的分身，没有面向自己的分身所在的场地安全。",-1)),l[23]||(l[23]=i("p",null,[s("读条"),i("mark",null,"燎原之炎"),s("后，场地中央仅剩余一块三角形区域安全，会依次出现 3 次击退提示，在第一次击退边中点观察并等待，被击退后立刻移动到第二次击退边的中点，以此类推。")],-1)),i("p",null,[l[8]||(l[8]=s("这个 BOSS 伤害极高，机制很快且密集，",-1)),t(n,{name:"healer"}),l[9]||(l[9]=s("治疗多关照团队血线，其他有救场能力的队员也尽量多关照队友。",-1))]),l[24]||(l[24]=r('<h2 id="boss-4-纳尔札尔" tabindex="-1">BOSS 4 纳尔札尔</h2><p>鳞片披风向上飘，发橙色的是纳尔，头顶有蓝色煤气灶火焰的是扎尔，所有生死之择的读条都需要观察 BOSS 形态进行判断（从第 2 次开始，BOSS 有可能在读条中途进行换人，换人时会有气泡提示，建议在读条后半再进行判断）：</p><ul><li><mark>生浪死环之择</mark> ： 橙色炸中间，蓝色炸周围，按相反颜色躲避。</li><li><mark>生轰死爆之择</mark> ： 橙色需要分摊的直线 AOE，蓝色追踪炮。建议被点蓝色点名的人远离人群，直到判定结束，若判定为蓝色的扎尔，则需要继续在场外绕场移动，待追踪炮伤害结束后回人群。</li><li><mark>生死袭火之择</mark> ： 出现扩散型 AOE 提示，根据颜色前往不会炸的 AOE 提示圈之间回避。这些 AOE 圈之间有极小的安全区，极限贴边的话也可以确保安全。</li><li><mark>生死混一之择</mark> ： 前两种的组合，先处理圆环机制，再处理分摊 / 追踪炮。</li></ul><p>其他技能：</p>',4)),i("ul",null,[l[13]||(l[13]=i("li",null,[i("mark",null,"炎天净火"),s("，点名 3 人扇形 AOE，1 人分摊。建议被点名扇形的人互不重叠远离，其他人尽可能靠近 BOSS 脚下进行分摊。")],-1)),i("li",null,[l[10]||(l[10]=i("mark",null,"纳尔神火",-1)),l[11]||(l[11]=s("，需要 3 个",-1)),t(n,{name:"tank"}),l[12]||(l[12]=s("T 进行分摊。",-1))]),l[14]||(l[14]=i("li",null,[i("mark",null,"炎狱破"),s("，紫色激光所向半场 AOE，读条中可能会变更方向。")],-1)),l[15]||(l[15]=i("li",null,[i("mark",null,"死魂爆"),s("：天上降落若干陨石，落地时 AOE 范围极大（AOE 直径与场地半径相同），需要走超过半场才能回避，注意观察陨石的位置和顺序进行回避。")],-1)),l[16]||(l[16]=i("li",null,[i("mark",null,"烈火之财"),s("：BOSS 移动到场边，并连线场地中随机若干个点，同时提示机制类型；第一次必定为【1 点】击退 +【2 点】远离，第二次需要观察后判断，如果出现连续击退难以调整，可以使用防击退技能处理。")],-1)),l[17]||(l[17]=i("li",null,[i("mark",null,"天秤之试炼"),s("：BOSS 上天，场地上出现 3 个影子并连线玩家，没有被连线的人请跟随自己小队队员。打倒影子后，之前被连线的玩家前往另外一半场地，没有被连线的玩家留在原地。观察场地北侧的天平，需要保证天平均衡，已站定 / 想不明白的玩家不要随意乱跑。若天平不平则会直接团灭。")],-1))]),l[25]||(l[25]=i("h2",{id:"其他参考攻略",tabindex:"-1"},"其他参考攻略",-1)),l[26]||(l[26]=i("ul",null,[i("li",null,[i("a",{href:"https://www.bilibili.com/video/BV1fW4y1171Z",target:"_blank",rel:"noreferrer"},"子言攻略（视频）")])],-1))])}const g=S(u,[["render",e]]);export{T as __pageData,g as default};
